import { test, expect } from '@playwright/test';

test.describe('Font Size Readability on Small Screens', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should display readable font size on small screen without zooming', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 667 });

    const header = page.getByRole('heading', { name: /main content/i });
    await expect(header).toBeVisible();

    const paragraph = page.getByText(/this is a paragraph of text/i);
    await expect(paragraph).toBeVisible();

    const button = page.getByRole('button', { name: /submit/i });
    await expect(button).toBeVisible();

    const fontSize = await header.evaluate((el) => parseFloat(window.getComputedStyle(el).fontSize));
    expect(fontSize).toBeGreaterThan(16);

    const paragraphFontSize = await paragraph.evaluate((el) => parseFloat(window.getComputedStyle(el).fontSize));
    expect(paragraphFontSize).toBeGreaterThan(14);

    const buttonFontSize = await button.evaluate((el) => parseFloat(window.getComputedStyle(el).fontSize));
    expect(buttonFontSize).toBeGreaterThan(14);
  });

  test('should maintain readable font size when screen size changes', async ({ page }) => {
    await page.setViewportSize({ width: 1200, height: 800 });

    const header = page.getByRole('heading', { name: /main content/i });
    await expect(header).toBeVisible();

    const paragraph = page.getByText(/this is a paragraph of text/i);
    await expect(paragraph).toBeVisible();

    const button = page.getByRole('button', { name: /submit/i });
    await expect(button).toBeVisible();

    const headerFontSize = await header.evaluate((el) => parseFloat(window.getComputedStyle(el).fontSize));
    expect(headerFontSize).toBeGreaterThan(24);

    await page.setViewportSize({ width: 375, height: 667 });

    const newHeaderFontSize = await header.evaluate((el) => parseFloat(window.getComputedStyle(el).fontSize));
    expect(newHeaderFontSize).toBeGreaterThan(16);

    const newParagraphFontSize = await paragraph.evaluate((el) => parseFloat(window.getComputedStyle(el).fontSize));
    expect(newParagraphFontSize).toBeGreaterThan(12);
  });
});
